<script>
  // Mock track and player state
  const track = {
    title: "Sacrifice",
    artist: "Mariah the Scientist — HEARTS SOLD SEPARATELY",
    duration: 79 // seconds (1:19 in screenshots)
  };

  const state = {
    playing: false,
    t: 7 // start a few seconds in like screenshot
  };

  // DOM references
  const miniBar = document.getElementById('miniBar');
  const topPlay = document.getElementById('top-play');
  const topPlayIcon = document.getElementById('top-play-icon');
  const openOverlay = document.getElementById('openOverlay');
  const overlay = document.getElementById('overlay');
  const closeOverlay = document.getElementById('closeOverlay');
  const seekBar = document.getElementById('seekBar');
  const seekFill = document.getElementById('seekFill');
  const bottomFill = document.getElementById('bottomFill');
  const curTime = document.getElementById('curTime');
  const durTime = document.getElementById('durTime');
  const npPlay = document.getElementById('np-play');
  const npPlayIcon = document.getElementById('np-play-icon');

  // Initialize labels
  document.getElementById('trackTitleMini').textContent = track.title;
  document.getElementById('titleNp').textContent = track.title;
  document.getElementById('artistNp').textContent = track.artist;
  durTime.textContent = formatTime(track.duration);

  function formatTime(s){
    s = Math.max(0, Math.floor(s));
    return Math.floor(s/60) + ":" + String(s%60).padStart(2,'0');
  }

  function updateUI(){
    const p = Math.min(100, (state.t/track.duration)*100);
    miniBar.style.width = p + "%";
    seekFill.style.width = p + "%";
    bottomFill.style.width = p + "%";
    curTime.textContent = formatTime(state.t);
    // Switch icons
    if(state.playing){
      topPlayIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/008.svg"; // pause
      npPlayIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/008.svg";
    }else{
      topPlayIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg"; // play
      npPlayIcon.src = "__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg";
    }
  }

  let timer = null;
  function play(){
    if(timer) return;
    state.playing = true;
    timer = setInterval(()=>{
      state.t += 0.25;
      if(state.t >= track.duration){
        state.t = 0;
      }
      updateUI();
    },250);
    updateUI();
  }
  function pause(){
    state.playing = false;
    clearInterval(timer); timer=null;
    updateUI();
  }
  function togglePlay(){
    state.playing ? pause() : play();
  }

  // Top bar controls
  topPlay.addEventListener('click', togglePlay);
  document.getElementById('np-prev').addEventListener('click', ()=>{
    state.t = Math.max(0, state.t - 5);
    updateUI();
  });
  document.getElementById('np-next').addEventListener('click', ()=>{
    state.t = Math.min(track.duration, state.t + 5);
    updateUI();
  });
  document.getElementById('top-prev').addEventListener('click', ()=>{
    state.t = Math.max(0, state.t - 5); updateUI();
  });
  document.getElementById('top-next').addEventListener('click', ()=>{
    state.t = Math.min(track.duration, state.t + 5); updateUI();
  });

  // Seek interactions (overlay)
  function seekAt(clientX, elem, onApply){
    const rect = elem.getBoundingClientRect();
    const ratio = Math.min(1, Math.max(0, (clientX - rect.left)/rect.width));
    const t = track.duration * ratio;
    onApply(t);
  }
  seekBar.addEventListener('click', (e)=>seekAt(e.clientX, seekBar, (t)=>{ state.t = t; updateUI(); }));

  // Overlay open / close
  openOverlay.addEventListener('click', ()=>{ overlay.classList.add('show'); });
  closeOverlay.addEventListener('click', ()=>{ overlay.classList.remove('show'); });

  // Play control from overlay
  npPlay.addEventListener('click', togglePlay);

  // Buttons in hero
  document.getElementById('getStarted').addEventListener('click', ()=>overlay.classList.add('show'));
  document.querySelector('.student').addEventListener('click', ()=>alert('Student Plan: mock link'));

  // Sidebar item active toggle
  document.querySelectorAll('.nav .item').forEach(li=>{
    li.addEventListener('click', ()=>{
      document.querySelectorAll('.nav .item').forEach(x=>x.classList.remove('active'));
      li.classList.add('active');
    });
  });

  // Start paused but with position visible
  updateUI();
</script>
</body>
